  // ── Needle plugin (for half-doughnut gauge) ───────────────
  const needlePlugin = {
    id: "adminNeedle",
    afterDatasetsDraw(chart) {
      const achievedArc = chart.getDatasetMeta(0)?.data?.[0];
      if (!achievedArc || !chart.$needleVisible) return;
      const { x, y, innerRadius, outerRadius, endAngle } = achievedArc.getProps(
        ["x", "y", "innerRadius", "outerRadius", "endAngle"], false
      );
      if (![x, y, innerRadius, outerRadius, endAngle].every(Number.isFinite)) return;
      const startRadius = Math.max(0, innerRadius);
      const endRadius   = Math.max(startRadius, outerRadius);
      const startX = x + Math.cos(endAngle) * startRadius;
      const startY = y + Math.sin(endAngle) * startRadius;
      const endX   = x + Math.cos(endAngle) * endRadius;
      const endY   = y + Math.sin(endAngle) * endRadius;
      const { ctx } = chart;
      ctx.save();
      ctx.beginPath();
      ctx.lineWidth = 2.5;
      ctx.lineCap = "butt";
      ctx.strokeStyle = "#dc2626";
      ctx.moveTo(startX, startY);
      ctx.lineTo(endX, endY);
      ctx.stroke();
      ctx.restore();
    }
  };

  // ── Chart registry ────────────────────────────────────────
  const charts = {};

  const buildChart = (id, config) => {
    const canvas = document.getElementById(id);
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const options = { ...baseOptions, ...(config.options || {}) };
    if (config.type === "doughnut") options.scales = {};
    charts[id] = new Chart(ctx, {
      type: config.type,
      data: config.data,
      options,
      plugins: config.plugins || []
    });
  };

