  function refreshCategoryCounts() {
    document.querySelectorAll("#kbCategoryGrid .kbCategoryCard").forEach(card => {
      const cat = card.dataset.cat;
      const count = kbArticles.filter(a => a.cat === cat).length;
      const countEl = card.querySelector(".kbCategoryCount");
      if (countEl) countEl.textContent = `${count} article${count !== 1 ? "s" : ""}`;
    });
    const allPillCount = document.getElementById("kbAllArticlesPillCount");
    if (allPillCount) allPillCount.textContent = `${kbArticles.length}`;
  }

  // ── Current ticket being viewed ─────────────────────────
  let currentTicketId = null;
  let currentTicketFilter = "all";

  // ── Ticket view setup ───────────────────────────────────
  function initRoleUI() {
    updateOpenCount();
  }

  function updateOpenCount() {
    const activeCount = getMyTickets().filter(t => t.status !== "closed").length;
    const badge = document.getElementById("openTicketCount");
    if (badge) badge.textContent = activeCount;
  }

  // ── Tab switching ───────────────────────────────────────
  function switchTab(tabId) {
    document.querySelectorAll(".hsTab").forEach(t => t.classList.remove("active"));
    document.querySelectorAll(".hsPanel").forEach(p => p.style.display = "none");

    const tab  = document.getElementById("tab" + tabId.charAt(0).toUpperCase() + tabId.slice(1));
    const panel = document.getElementById("panel" + tabId.charAt(0).toUpperCase() + tabId.slice(1));
    if (tab) tab.classList.add("active");
    if (panel) panel.style.display = "";

    if (tabId === "tickets") {
      document.getElementById("ticketAccessGate").style.display = "none";
      document.getElementById("ticketContent").style.display = "";
      renderTickets(currentTicketFilter);
      renderTicketKpis();
    }
    if (tabId === "feedback") {
      renderFeedbackHistory();
    }
  }

  window.switchTab = switchTab;

  document.querySelectorAll(".hsTab").forEach(tab => {
    tab.addEventListener("click", () => switchTab(tab.dataset.tab));
  });

